<?php $circles=$a->db->all('SELECT * FROM cy_categories WHERE is_circle=1 ORDER BY sort_order,id');$selected=(int)($_GET['category_id']??($circles[0]['id']??0));$choices=[];foreach($circles as $circle){$choices[$circle['id']]=$circle['name'];}$page=max(1,min(100000,(int)($_GET['page']??1)));$memberPage=max(1,min(100000,(int)($_GET['member_page']??1)));$memberTotal=$selected?(int)$a->db->value('SELECT COUNT(*) FROM cy_circle_members WHERE category_id=?',[$selected]):0;$members=$selected?$a->db->all('SELECT m.*,u.display_name,u.username FROM cy_circle_members m JOIN cy_users u ON u.id=m.user_id WHERE m.category_id=? ORDER BY m.updated_at DESC,m.id DESC LIMIT 50 OFFSET ?',[$selected,($memberPage-1)*50]):[];$orders=$selected?$a->db->all("SELECT o.*,u.display_name FROM cy_orders o JOIN cy_users u ON u.id=o.user_id WHERE o.kind='circle' AND o.item_id=? ORDER BY o.id DESC LIMIT 30 OFFSET ?",[$selected,($page-1)*30]):[];$total=$selected?(int)$a->db->value("SELECT COUNT(*) FROM cy_orders WHERE kind='circle' AND item_id=?",[$selected]):0; ?>
<div class="admin-title"><div><span class="eyebrow">COMMUNITY / ACCESS WITH INTENT</span><h1><?= t('Circle memberships') ?></h1><p><?= t('Purchased terms, manual grants and suspensions share one access policy. Refunds revoke only the refunded term.') ?></p></div><a class="btn" href="<?= e(au('categories')) ?>"><?= icon('plus') ?><?= t('Configure circles') ?></a></div>
<?php if(!$circles): empty_state('Create a forum category and enable circle membership.','users'); else: ?>
<form method="get" class="panel section"><input type="hidden" name="tab" value="circles"><?php select_field('category_id','Circle',$choices,$selected);button('Show memberships','secondary','users'); ?></form>
<div class="admin-edit-grid"><section class="panel"><h2><?= t('Purchased memberships') ?></h2><div class="table-wrap"><table class="data-table"><thead><tr><th><?= t('Member') ?></th><th><?= t('Order') ?></th><th><?= t('Status') ?></th><th><?= t('Expiry') ?></th></tr></thead><tbody><?php foreach($orders as $row): ?><tr><td><?= e($row['display_name']) ?> #<?= (int)$row['user_id'] ?></td><td><a href="<?= e(au('orders',['q'=>$row['order_no']])) ?>"><?= e($row['order_no']) ?></a></td><td><span class="pill"><?= t($row['status']) ?></span></td><td><?= (int)$row['access_until']?dt((int)$row['access_until']):t('Permanent') ?></td></tr><?php endforeach ?></tbody></table></div><?php if(!$orders){empty_state();}partial('pagination',['tab'=>'circles','pagination'=>['page'=>$page,'pages'=>max(1,(int)ceil($total/30))]]); ?></section>
<section class="panel"><h2><?= t('Grant or suspend membership') ?></h2><?= form_start('admin_circle_member') . hidden('category_id',$selected) ?><?php field('user_id','User ID','','number',['min'=>'1','required'=>'required']);field('granted_until','Manual access until (blank removes manual grant)','','datetime-local');check_field('blocked','Suspend access, including paid membership',false);button(); ?><p class="hint"><?= t('Unchecking suspension restores valid paid access. Empty expiry only removes the manual grant. Suspension does not automatically refund money.') ?></p></form></section></div>
<section class="panel section"><h2><?= t('Manual access overrides') ?></h2><div class="table-wrap"><table class="data-table"><thead><tr><th><?= t('Member') ?></th><th><?= t('Suspended') ?></th><th><?= t('Manual grant expiry') ?></th></tr></thead><tbody><?php foreach($members as $member): ?><tr><td><?= e($member['display_name']) ?> #<?= (int)$member['user_id'] ?></td><td><?= t($member['blocked']?'Yes':'No') ?></td><td><?= (int)$member['granted_until']?dt((int)$member['granted_until']):t('None') ?></td></tr><?php endforeach ?></tbody></table></div><?php partial('pagination',['tab'=>'circles','pagination'=>['page'=>$memberPage,'pages'=>max(1,(int)ceil($memberTotal/50))],'page_key'=>'member_page']); ?></section><?php endif ?>
